        for (0..n) |j| {
            if (matrix[i][j] == row_max[i] and matrix[i][j] == col_min[j]) {
                try list.append(Point{
                    .row = @intCast(i + 1),
                    .column = @intCast(j + 1),
                });
            }
        }
    }

    return list.toOwnedSlice();
}
